script:
// Excel 导出 - 模板填充示例
// 查询数据
var data = db.select("select id, username, email, create_time from sys_user where is_del = 0 limit 10")

// 使用模板填充（模板文件放在 resources/excel-templates/目录下）
// 模板中需要有对应的填充区域，如：{.data}
excel.downloadWithTemplate("user_template.xlsx", data, "用户导出_" + System.currentTimeMillis())
